@push('scripts')
<script>
$(function(){const form=$('#customer-form'),box=$('#duplicate-results'),submit=form.find('[type=submit]'),url=@json(route('crm.customers.duplicate-options'));let timer,request;function check(){if(request)request.abort();const fields=['name','tax_id','branch_code','phone','email'],params=new URLSearchParams;fields.forEach(name=>params.set(name,form.find('[name="'+name+'"]').val()||''));params.set('exclude_id',@json($customer->id));if(!params.get('name')&&!params.get('tax_id')&&!params.get('phone')&&!params.get('email')){box.addClass('d-none').empty();submit.prop('disabled',false);return;}request=$.getJSON(url,params.toString()).done(function(data){submit.prop('disabled',!!data.hard_match);if(!data.results.length){box.addClass('d-none').empty();return;}box.removeClass('d-none').html('<div class="alert '+(data.hard_match?'alert-warning':'alert-info')+' mb-0"><strong>'+(data.hard_match?'พบลูกค้าที่มี Tax ID หรือเบอร์โทรตรงกัน':'พบลูกค้าที่อาจซ้ำ')+'</strong><div class="mt-2 js-duplicate-list"></div></div>');const list=box.find('.js-duplicate-list');data.results.forEach(customer=>{const row=$('<div class="d-flex justify-content-between align-items-center gap-2 border-top pt-2 mt-2"></div>').append($('<span></span>').text(customer.text+(customer.similarity_reason?' · '+customer.similarity_reason:'')));if(customer.can_select)row.append($('<a class="btn btn-sm btn-app-soft">เปิดข้อมูลเดิม</a>').attr('href',@json(route('crm.customers.show',['customer'=>'__ID__'])).replace('__ID__',customer.id)));list.append(row);});});}form.on('input change','[name=name],[name=tax_id],[name=branch_code],[name=phone],[name=email]',function(){clearTimeout(timer);timer=setTimeout(check,300);});window.erpAjaxForm({form:'#customer-form',redirect:true});});
</script>
@endpush
